<script>
(()=>{const make=(ok,fail)=>new Proxy({}, {get:(_,key)=>{if(key==='withSuccessHandler')return cb=>make(cb,fail);if(key==='withFailureHandler')return cb=>make(ok,cb);return (...args)=>fetch('api.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:String(key),args})}).then(async r=>{const v=await r.json();if(!r.ok||v&&v.error)throw new Error(v.error||'Request failed');return v}).then(v=>{if(ok)ok(v);return v}).catch(e=>{if(fail)fail(e);else console.error(e)})}});window.google={script:{run:make(null,null)}};if(/[?&]page=(admin|frontdesk|kitchen|rider)(?:&|$)/i.test(location.search)){const keepStaffAlive=()=>fetch('api.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:'keepStaffSession',args:[]})}).catch(()=>{});window.setInterval(keepStaffAlive,60*1000);document.addEventListener('visibilitychange',keepStaffAlive);window.addEventListener('focus',keepStaffAlive)}})();
</script>
