$brandBridge=<<<'HTML'
<script>
(()=>{window.applyBrandSettings=settings=>{if(!settings)return;window.brandConfig=settings;const name=String(settings.businessName||'FOODTRAPS CAFÉ'),tagline=String(settings.tagline||'Where Good Taste Costs No More'),logo=String(settings.logoUrl||'assets/foodtraps-logo.png'),primary=/^#[0-9a-f]{6}$/i.test(settings.primaryColor||'')?settings.primaryColor:'#5b351f',page=/^#[0-9a-f]{6}$/i.test(settings.pageColor||'')?settings.pageColor:'#f4efe7',fonts=['Arial','Georgia','Verdana','Tahoma','Trebuchet MS','system-ui'],font=fonts.includes(settings.fontFamily)?settings.fontFamily:'Arial',size=[13,15,17].includes(Number(settings.fontSize))?Number(settings.fontSize):15;document.querySelectorAll('.brand img,header img,img[alt="Foodtraps Café"]').forEach(img=>{img.src=logo});document.querySelectorAll('.brand h1').forEach(el=>el.textContent=name);document.querySelectorAll('.brand p').forEach(el=>el.textContent=tagline.toUpperCase());document.querySelectorAll('header b').forEach(el=>{if(/^FOODTRAPS CAFÉ$/i.test(el.textContent.trim()))el.textContent=name});document.querySelectorAll('header h1').forEach(el=>{if(/^FOODTRAPS CAFÉ\s+—/i.test(el.textContent.trim()))el.textContent=el.textContent.replace(/^FOODTRAPS CAFÉ/i,name)});document.querySelectorAll('.login-eyebrow').forEach(el=>{if(/^FOODTRAPS CAFÉ$/i.test(el.textContent.trim()))el.textContent=name.toUpperCase()});document.querySelectorAll('.id-header-title,.back-header-title').forEach(el=>el.textContent=name.toUpperCase());document.title=document.title.replace(/^Foodtraps Café/i,name);let theme=document.getElementById('saved-brand-theme');if(!theme){theme=document.createElement('style');theme.id='saved-brand-theme';document.head.appendChild(theme)}theme.textContent=`:root{--saved-brand-primary:${primary};--saved-brand-page:${page};--saved-brand-font:"${font}";--saved-brand-font-size:${size}px}body,body *{font-family:var(--saved-brand-font),sans-serif!important}body{font-size:var(--saved-brand-font-size)!important;background-color:var(--saved-brand-page)!important}header{background:var(--saved-brand-primary)!important}.primary,.btn.primary,.ok{background:var(--saved-brand-primary)!important;border-color:var(--saved-brand-primary)!important}.nav button:hover{background:var(--saved-brand-primary)!important;color:#fff!important}input,select,textarea,button{font-family:var(--saved-brand-font),sans-serif!important}`;const background=String(settings.backgroundUrl||'');if(/^assets\/company-branding-background\.(png|jpg|webp)(\?v=[\w-]+)?$/.test(background)){document.body.style.backgroundImage=`url("${background}")`;document.body.style.backgroundPosition='center';document.body.style.backgroundSize='cover';document.body.style.backgroundAttachment='fixed';document.body.style.backgroundRepeat='no-repeat'}else document.body.style.removeProperty('background-image')};const load=()=>fetch('api.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({method:'getPublicStaffConfig',args:[]})}).then(r=>r.json()).then(window.applyBrandSettings).catch(()=>{});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load,{once:true});else load()})();
</script>
